<template>
 <section class="research-checks" aria-label="研究检查">
  <div class="checks-heading"><div><h3>把候选变成有记录的判断</h3><p>固定输入 → 训练与验证 → 锁定候选 → 保留测试 → 研究结论</p></div><el-button :disabled="!canEdit||!completed.length" @click="configure">新建检查</el-button></div>
  <p class="checks-note">使用当前项目已完成的因子实验输入。只比较单合约时序，不作跨资产排名。</p>
  <el-table :data="projectChecks" empty-text="先完成一个因子实验，再固定它的输入检查候选。"><el-table-column prop="code" label="合约" min-width="140"/><el-table-column label="进度" min-width="125"><template #default="{row}">{{statusLabel(row.status)}}</template></el-table-column><el-table-column label="结论" width="100"><template #default="{row}">{{lifecycleLabel(row.lifecycle)}}</template></el-table-column><el-table-column label="候选数" width="85"><template #default="{row}">{{row.candidates.length}}</template></el-table-column><el-table-column label="保留测试" width="100"><template #default="{row}">{{row.test_revealed?'已揭示':'未揭示'}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text @click="open(row)">查看检查</el-button></template></el-table-column></el-table>
  <template v-if="detail">
   <div class="checks-heading"><h3>{{detail.workflow.code}} · {{statusLabel(detail.workflow.status)}}</h3><el-button text @click="refreshDetail">刷新详情</el-button></div>
   <el-alert v-if="detail.workflow.error" :title="detail.workflow.error" type="error" :closable="false"/>
   <p class="checks-note">{{detail.workflow.holdout_note}}</p>
   <template v-if="detail.analysis">
    <div class="checks-split"><div><strong>训练 {{detail.analysis.split.train_percent}}%</strong><span>{{stamp(detail.analysis.split.start)}} 起</span></div><div><strong>验证 {{detail.analysis.split.validation_percent}}%</strong><span>{{stamp(detail.analysis.split.validation_start)}} 起</span></div><div><strong>保留测试 {{detail.analysis.split.test_percent}}%</strong><span>{{stamp(detail.analysis.split.test_start)}} 起</span></div></div>
    <p class="checks-note">时间顺序先固定。若一条未来收益标签跨过分割点，就从前一区间剔除。候选方向只用训练段确定，按验证段比较。</p>
    <el-table :data="detail.analysis.candidates" highlight-current-row><el-table-column label="候选 / 窗口" min-width="190"><template #default="{row}">{{row.name}} · {{row.lookback}} 根 <small v-if="row.id===detail.analysis.recommended_candidate_id">建议检查</small></template></el-table-column><el-table-column label="训练 RankIC" width="130"><template #default="{row}">{{number(row.train.rank_ic)}}</template></el-table-column><el-table-column label="验证 RankIC" width="130"><template #default="{row}">{{number(row.validation.rank_ic)}}</template></el-table-column><el-table-column label="验证有效样本" width="120"><template #default="{row}">{{row.validation.paired_rows}}</template></el-table-column><el-table-column label="跨界剔除 训/验" width="135"><template #default="{row}">{{row.purged_train}} / {{row.purged_validation}}</template></el-table-column><el-table-column label="训练期相关去重" min-width="145"><template #default="{row}">{{row.redundant_with?'近似 '+candidateName(row.redundant_with):'保留比较'}}</template></el-table-column><el-table-column label="选择" width="100"><template #default="{row}"><el-button text :disabled="!canEdit||detail.workflow.status!=='review'||detail.workflow.lifecycle!=='candidate'" @click="choose(row)">{{row.id===detail.workflow.selected_candidate_id?'已选定':'选定候选'}}</el-button></template></el-table-column></el-table>
    <p class="checks-note">RankIC是因子排序与后续收益排序的相关。此处按时间点排序；重叠标签不是相互独立的样本。去重仅比较训练期自身因子，不表示市场拥挤。</p>
    <template v-if="selectedCandidate"><h3>{{selectedCandidate.name}} · {{selectedCandidate.lookback}} 根：验证段稳定性</h3><el-table :data="selectedCandidate.validation_stability"><el-table-column prop="segment" label="按时间分段" width="120"/><el-table-column prop="paired_rows" label="有效样本"/><el-table-column label="RankIC"><template #default="{row}">{{number(row.rank_ic)}}</template></el-table-column><el-table-column label="分组单调性"><template #default="{row}">{{number(row.group_monotonicity)}}</template></el-table-column></el-table></template>
    <details class="checks-details"><summary>训练期因子相关与分割记录</summary><p>相关阈值：{{detail.analysis.redundancy_threshold}}。优先保留训练期绝对RankIC较高的候选。</p><el-table :data="detail.analysis.correlations"><el-table-column label="候选A"><template #default="{row}">{{candidateName(row.left)}}</template></el-table-column><el-table-column label="候选B"><template #default="{row}">{{candidateName(row.right)}}</template></el-table-column><el-table-column label="时序秩相关"><template #default="{row}">{{number(row.rank_correlation)}}</template></el-table-column><el-table-column prop="rows" label="对齐样本"/></el-table><pre>{{JSON.stringify(detail.analysis.split,null,2)}}</pre></details>
    <div class="checks-test"><h3>只揭示已选定候选的保留测试</h3><p v-if="!detail.workflow.test_revealed">先选定候选。揭示后，这条检查不能再换候选。保留测试不参与候选比较。</p><el-button v-if="!detail.workflow.test_revealed" type="primary" :loading="revealing" :disabled="!canEdit||!detail.workflow.selected_candidate_id||detail.workflow.lifecycle!=='candidate'" @click="reveal">锁定选择并揭示保留测试</el-button><template v-else><p>有效样本 {{detail.analysis.test.paired_rows}} · RankIC {{number(detail.analysis.test.rank_ic)}} · 沿训练方向 {{number(detail.analysis.test.oriented_rank_ic)}}</p><el-table :data="detail.analysis.test.stability"><el-table-column prop="segment" label="测试时间分段"/><el-table-column prop="paired_rows" label="有效样本"/><el-table-column label="RankIC"><template #default="{row}">{{number(row.rank_ic)}}</template></el-table-column></el-table></template></div>
    <h3>保存研究判断</h3><p class="checks-note">采纳只登记研究候选，继续由WT回测检验成交与费用。它不会替换任何正在运行的策略。</p><el-input v-model="decisionNote" type="textarea" :rows="3" placeholder="为何采纳、拒绝或退役？写清后续要用WT检验的问题。" aria-label="研究判断原因"/><div class="checks-decisions"><el-button :disabled="!canEdit||!detail.workflow.test_revealed||detail.workflow.lifecycle!=='candidate'" @click="decide('accepted')">采纳为研究候选</el-button><el-button :disabled="!canEdit||detail.workflow.lifecycle!=='candidate'" @click="decide('rejected')">拒绝</el-button><el-button :disabled="!canEdit||detail.workflow.lifecycle!=='accepted'" @click="decide('retired')">退役</el-button></div><p v-if="detail.workflow.decision_note">{{lifecycleLabel(detail.workflow.lifecycle)}}：{{detail.workflow.decision_note}}</p>
   </template>
  </template>
  <el-dialog v-model="configuring" title="固定输入并比较小范围候选" width="min(650px,94vw)"><el-form label-position="top"><el-form-item label="当前项目已完成的因子实验"><el-select v-model="form.input_experiment_id" aria-label="固定研究输入" @change="selectSource"><el-option v-for="item in completed" :key="item.id" :value="item.id" :label="item.code+' · '+item.period+' · '+item.id.slice(0,8)"/></el-select></el-form-item><el-form-item label="比较因子（最多3个）"><el-select v-model="form.factor_ids" multiple :multiple-limit="3" aria-label="候选因子"><el-option v-for="item in factors" :key="item.id" :value="item.id" :label="item.name+' · v'+item.version"/></el-select></el-form-item><el-form-item label="候选回看窗口（1至3个，逗号分隔）"><el-input v-model="windowText" placeholder="例如 10,20,40" aria-label="候选回看窗口"/></el-form-item><p class="checks-note">最多比较9个组合。固定训练60%、验证20%、保留测试20%。评价持有期沿用输入实验，禁止测试结果反过来挑窗口。</p></el-form><template #footer><el-button @click="configuring=false">取消</el-button><el-button type="primary" :loading="launching" @click="run">保存输入并开始检查</el-button></template></el-dialog>
 </section>
</template>
<script>
export default {
 name:'ResearchWorkflow',props:{project:{type:Object,required:true},factors:{type:Array,default:()=>[]},experiments:{type:Array,default:()=>[]},workflows:{type:Array,default:()=>[]},canEdit:Boolean},emits:['refresh'],
 data:()=>({detail:null,configuring:false,launching:false,revealing:false,decisionNote:'',windowText:'',form:{input_experiment_id:'',factor_ids:[]}}),
 computed:{completed(){return this.experiments.filter(x=>x.project_id===this.project.id&&x.status==='completed')},projectChecks(){return this.workflows.filter(x=>x.project_id===this.project.id)},selectedCandidate(){return this.detail?.analysis?.candidates.find(x=>x.id===this.detail.workflow.selected_candidate_id)}},
 watch:{workflows(){if(this.detail&&['comparing','testing'].includes(this.detail.workflow.status))this.refreshDetail()},project(){this.detail=null}},
 methods:{number(value){return value==null?'—':Number(value).toFixed(4)},stamp(value){const t=String(value||'');return t.slice(0,4)+'-'+t.slice(4,6)+'-'+t.slice(6,8)+' '+t.slice(8,10)+':'+t.slice(10,12)},statusLabel(value){return {comparing:'比较训练与验证',review:'等待选定候选',testing:'计算保留测试',evaluated:'测试已揭示',failed:'检查失败',interrupted:'已中断'}[value]||value},lifecycleLabel(value){return {candidate:'待判断',accepted:'已采纳',rejected:'已拒绝',retired:'已退役'}[value]||value},candidateName(id){const row=this.detail?.analysis?.candidates.find(x=>x.id===id);return row?row.name+' / '+row.lookback:id},
 async request(action,body){const response=await fetch('/mgr/research/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok||data.result<0)throw new Error(data.message||'研究检查失败');return data},configure(){this.form={input_experiment_id:this.completed[0]?.id||'',factor_ids:[]};this.selectSource();this.configuring=true},selectSource(){const source=this.completed.find(x=>x.id===this.form.input_experiment_id);if(source){this.form.factor_ids=[source.factor_id];this.windowText=String(source.factor_snapshot.lookback)}},async run(){const windows=this.windowText.split(/[,，\s]+/).filter(Boolean).map(Number);if(!windows.length||windows.length>3||windows.some(x=>!Number.isInteger(x)||x<2||x>500)){this.$message.error('请输入1至3个2到500的整数窗口');return}this.launching=true;try{const data=await this.request('workflow_run',{...this.form,project_id:this.project.id,windows});this.configuring=false;this.detail={workflow:data.workflow,analysis:null};this.$emit('refresh')}catch(error){this.$message.error(error.message)}finally{this.launching=false}},async open(row){try{this.detail=await this.request('workflow_detail',{workflow_id:row.id});this.decisionNote=''}catch(error){this.$message.error(error.message)}},async refreshDetail(){if(this.detail)await this.open(this.detail.workflow)},async choose(row){try{await this.request('workflow_choose',{workflow_id:this.detail.workflow.id,candidate_id:row.id});await this.refreshDetail();this.$emit('refresh')}catch(error){this.$message.error(error.message)}},async reveal(){this.revealing=true;try{this.detail=await this.request('workflow_reveal',{workflow_id:this.detail.workflow.id});this.$emit('refresh')}catch(error){this.$message.error(error.message)}finally{this.revealing=false}},async decide(lifecycle){if(!this.decisionNote.trim()){this.$message.error('请先填写具体判断原因');return}try{await this.request('workflow_decide',{workflow_id:this.detail.workflow.id,lifecycle,note:this.decisionNote});await this.refreshDetail();this.$emit('refresh')}catch(error){this.$message.error(error.message)}}}
}
</script>
<style scoped>
.checks-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.checks-heading p,.checks-note{color:var(--wt-muted);font-size:12px;line-height:1.8}.checks-split{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0}.checks-split>div{display:flex;flex-direction:column;gap:8px;border:1px solid var(--wt-line);padding:16px;border-radius:6px}.checks-split span{font-size:11px;color:var(--wt-muted)}h3{font-size:15px;font-weight:550;margin:24px 0 12px}.checks-details{margin:20px 0}.checks-details summary{cursor:pointer}.checks-details pre{white-space:pre-wrap;font-size:12px;background:var(--wt-matte);padding:14px}.checks-test{padding:1px 18px 18px;background:var(--wt-matte);border:1px solid var(--wt-line);border-radius:6px;margin-top:20px}.checks-decisions{display:flex;gap:9px;flex-wrap:wrap;margin:14px 0}.el-select{width:100%}small{color:var(--wt-muted)}@media(max-width:650px){.checks-heading{align-items:flex-start;flex-direction:column}.checks-split{grid-template-columns:1fr}}
</style>
